/**
 * Daily Top Reels selector — n8n Code node ("Run Once for All Items").
 *
 * INPUT (one item per scraped row). Each item.json must contain the scraper
 * fields PLUS the previous snapshot attached by an upstream "Data Table > Get"
 * node (null/undefined if the reel was never seen before):
 *   product_type, like_count, comment_count, play_count, ig_play_count,
 *   reshare_count, taken_at_timestamp, id, shortcode, url, gd_file_id, ...
 *   prev_views, prev_likes, prev_seen_ts   <-- from Data Table lookup (by shortcode)
 *
 * OUTPUT: every reel that passes the quality gates, scored + ranked + momentum
 * flags. The top N NOT-yet-used reels carry is_pick=true. Downstream
 * "Data Table > Upsert" writes back the new snapshot, keyed on shortcode.
 */

// ---------------------------------------------------------------- CONFIG
const CFG = {
  MIN_VIEWS:      10000,    // hard floor: drop sub-noise reels
  MIN_LIKE_RATE:  0.01,    // hard floor: kills inflated/dead views (3 likes / 160k)
  HALF_LIFE_DAYS: 14,      // recency decay: 14d old => recency ~0.5
  W_VIEWS:        0.30,    // weight: reach (percentile)
  W_LIKE:         0.30,    // weight: like quality (percentile)
  W_ENG:          0.20,    // weight: total engagement (percentile)
  W_RECENCY:      0.20,    // weight: freshness (exp decay, 0..1)
  MOMENTUM_PCT:   0.20,    // +20% views since last snapshot => momentum
  MOMENTUM_BONUS: 0.10,    // score nudge so re-accelerating reels resurface
  TOP_N:          5,       // how many to mark as picks
  ADDED_FIELD:    'status',        // sheet column holding the used/queued status
  ADDED_VALUE:    'moved_to_top',  // value that means "already added" -> skip from picks
};

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

// Accept either a unix-epoch (number or numeric string) or an ISO datetime
// string and return milliseconds since epoch. Returns NaN if unparseable.
const toMs = (v) => {
  if (v == null || v === '') return NaN;
  if (typeof v === 'number') return v * 1000;          // epoch seconds
  if (/^\d+$/.test(String(v).trim())) return Number(v) * 1000; // "1781119335"
  const t = Date.parse(v);                              // "2026-06-10T19:22:15+00:00"
  return Number.isFinite(t) ? t : NaN;
};

// percentile rank (0..1) of each value within an array (ties -> average rank)
function percentiles(values) {
  const sorted = [...values].sort((a, b) => a - b);
  return values.map((v) => {
    let lo = 0, hi = 0;
    for (const s of sorted) { if (s < v) lo++; if (s <= v) hi++; }
    return (lo + hi) / 2 / sorted.length; // midrank / n
  });
}

const nowMs = Date.now();
const rows = $input.all().map((i) => i.json);

// ----------------------------------------------------- GATES + FEATURES
const gated = [];
for (const r of rows) {
  if (r.product_type !== 'clips') continue;             // reels only

  const views  = Math.max(num(r.play_count), num(r.ig_play_count));
  const likes  = num(r.like_count);
  const comments = num(r.comment_count);
  const shares = num(r.reshare_count);
  const likeRate = views > 0 ? likes / views : 0;

  if (views < CFG.MIN_VIEWS) continue;                  // floor: reach
  if (likeRate < CFG.MIN_LIKE_RATE) continue;           // floor: kills fake views

  const engRate = views > 0 ? (likes + comments + shares) / views : 0;
  let tsMs = toMs(r.taken_at);                          // epoch field first
  if (!Number.isFinite(tsMs)) tsMs = toMs(r.taken_at_timestamp); // ISO fallback
  const ageDays = Number.isFinite(tsMs) ? (nowMs - tsMs) / 86400000 : 9999;
  const recency = Math.exp(-ageDays / CFG.HALF_LIFE_DAYS);

  // ---- momentum vs previous snapshot ----
  const prevViews = r.prev_views != null ? num(r.prev_views) : null;
  const prevLikes = r.prev_likes != null ? num(r.prev_likes) : null;
  const isNew = prevViews == null;
  const dViews = isNew ? 0 : views - prevViews;
  const dLikes = isNew ? 0 : likes - prevLikes;
  const prevSeenMs = r.prev_seen_ts ? new Date(r.prev_seen_ts).getTime() : null;
  const daysSince = prevSeenMs ? Math.max((nowMs - prevSeenMs) / 86400000, 1) : null;
  const velocity = daysSince ? dViews / daysSince : 0; // views/day since last run
  const grewPct = prevViews && prevViews > 0 ? dViews / prevViews : 0;
  const momentum = !isNew && grewPct >= CFG.MOMENTUM_PCT;

  gated.push({
    ...r,
    views, likes, comments, shares,
    like_rate: likeRate, eng_rate: engRate,
    age_days: ageDays, recency,
    is_new: isNew, d_views: dViews, d_likes: dLikes,
    velocity, grew_pct: grewPct, momentum,
  });
}

// ------------------------------------------------- PERCENTILES + SCORE
const pV = percentiles(gated.map((g) => g.views));
const pL = percentiles(gated.map((g) => g.like_rate));
const pE = percentiles(gated.map((g) => g.eng_rate));

gated.forEach((g, idx) => {
  g.p_views = pV[idx];
  g.p_like  = pL[idx];
  g.p_eng   = pE[idx];
  g.score =
    CFG.W_VIEWS   * g.p_views +
    CFG.W_LIKE    * g.p_like +
    CFG.W_ENG     * g.p_eng +
    CFG.W_RECENCY * g.recency +
    (g.momentum ? CFG.MOMENTUM_BONUS : 0);
});

// --------------------------------------------------- RANK + MARK PICKS
gated.sort((a, b) => b.score - a.score);
let picked = 0;
gated.forEach((g, i) => {
  g.rank = i + 1;
  // exclude already-used reels from picks, but keep them in the pool so
  // percentiles stay stable and their snapshot keeps updating.
  const alreadyAdded =
    String(g[CFG.ADDED_FIELD] || '').trim() === CFG.ADDED_VALUE;
  g.is_pick = !alreadyAdded && picked < CFG.TOP_N;
  if (g.is_pick) picked++;
  g.flag = g.is_new ? 'new' : (g.momentum ? 'momentum' : 'tracked');
  // snapshot fields for the downstream Data Table > Upsert (key = shortcode)
  g.snap_shortcode = g.shortcode;
  g.snap_views = g.views;
  g.snap_likes = g.likes;
  g.snap_seen_ts = new Date(nowMs).toISOString().slice(0, 10);
});

return gated.map((json) => ({ json }));

function escMrkdwn(value) {
  if (value == null) return '';

  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function oneLine(value, maxLength) {
  const text = String(value || '')
    .replace(/\s+/g, ' ')
    .trim();

  if (!text) return '';

  return text.length > maxLength
    ? text.slice(0, maxLength - 1) + '…'
    : text;
}

function fmtNum(value) {
  const number = Number(value);

  if (!Number.isFinite(number)) return '—';

  return number.toLocaleString('en-US');
}

function pct(value) {
  const number = Number(value);

  if (!Number.isFinite(number)) return '—';

  return (number * 100).toFixed(2) + '%';
}

function validHttpUrl(value) {
  if (!value) return '';

  const text = String(value).trim();

  try {
    const url = new URL(text);

    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return '';
    }

    return url.toString();
  } catch {
    return '';
  }
}

return $input.all().map((item) => {
  const j = item.json || {};

  const rank = j.rank ?? '—';
  const author = oneLine(j.author, 80) || 'unknown';
  const shortcode = oneLine(j.shortcode, 100) || '—';
  const flag = oneLine(j.flag, 50) || 'tracked';

  const views = fmtNum(j.views);
  const likes = fmtNum(j.likes);
  const likeRate = pct(j.like_rate);

  const score = Number.isFinite(Number(j.score))
    ? Number(j.score).toFixed(3)
    : '—';

  const generatedInstagramUrl =
    shortcode !== '—'
      ? `https://www.instagram.com/reel/${encodeURIComponent(shortcode)}/`
      : '';

  const instagramUrl =
    validHttpUrl(j.url) || generatedInstagramUrl;

  const googleDriveUrl =
    validHttpUrl(j.link_to_gdrive);

  const caption = oneLine(j.caption, 180);

  const flagEmoji =
    flag === 'new'
      ? ':sparkles:'
      : flag === 'momentum'
        ? ':chart_with_upwards_trend:'
        : ':repeat:';

  const lines = [
    `${flagEmoji} *Daily Top Reel #${escMrkdwn(rank)}* · ${escMrkdwn(author)} · \`${escMrkdwn(shortcode)}\``,
    `*Score:* ${escMrkdwn(score)} · *Flag:* ${escMrkdwn(flag)}`,
    `*Views:* ${escMrkdwn(views)} · *Likes:* ${escMrkdwn(likes)} · *Like rate:* ${escMrkdwn(likeRate)}`,
  ];

  if (caption) {
    lines.push(`*Caption:* ${escMrkdwn(caption)}`);
  }

  if (instagramUrl) {
    lines.push(`<${instagramUrl}|Open on Instagram>`);
  }

  if (googleDriveUrl) {
    lines.push(`<${googleDriveUrl}|Open on Google Drive>`);
  }

  const fallback = [
    `Daily Top Reel #${rank} · ${author} · ${shortcode}`,
    `Score ${score} · ${flag}`,
    `Views ${views} · Likes ${likes} · Like rate ${likeRate}`,
    instagramUrl,
    googleDriveUrl,
  ]
    .filter(Boolean)
    .join('\n');

  const blocks = [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: lines.join('\n'),
      },
    },
  ];

  return {
    json: {
      slackBody: {
        text: fallback,
        blocks,
      },
    },
  };
});
